            idx=col_to_idx(c.attrib['r']); maxidx=max(maxidx,idx); d[idx]=cell_val(c, ss)
        arr=[d.get(i,'') for i in range(maxidx+1)]
        if any(arr): print(row.attrib.get('r'), arr)
